"""Compute the falling factorial of n to depth k.

    >>> falling(6, 3)  # 6 * 5 * 4
    120
    >>> falling(4, 3)  # 4 * 3 * 2
    24
    >>> falling(4, 1)  # 4
    4
    >>> falling(4, 0)
    1
    """
def falling(n: Any, k: Any) -> object {
    if not k {
        return 1;
    } else {
        output = n;
        while (k != 1) {
            output = output * (n - 1);
            n = n - 1;
            k -= 1;
        }
        return output;
    }
}

